"""File containing common operations for Monaco interactions and other general Monaco utility functions."""

from interops.libraries.squish_actions import CommonActions
import sys, os
from remotesystem import RemoteSystem
from polling2 import poll, TimeoutException


def get_monaco_image_folder_path() -> str:
    """Gets the path for the current python installation and appends it to the images path in the
    monaco library. Returns absolute path to the monaco images folder.

    :return: Absolute path of the monaco images folder
    :rtype: str
    """
    # Get the current python installation path
    python_install_path = sys.exec_prefix
    monaco_images_path = "Lib/site-packages/interops/libraries/monaco/interactions/images"
    python_install_and_monaco_images_path = os.path.abspath(os.path.join(
        python_install_path, monaco_images_path))
    return python_install_and_monaco_images_path


def clear_textfield(textfieldObject: dict) -> None:
    """Clicks on the given textfieldObject > highlight the entire content of the textfieldObject with Shift+Ctrl+A >
    inputs the delete key press

    :param textfieldObject: Object Map of the target textbox
    :type textboxObject: dict
    """
    CommonActions.left_click_object(textfieldObject)
    CommonActions.press_key_sequence_ctrl_a()
    CommonActions.press_delete_key()

def is_monaco_adaptive_script_process_running(serverAddress:str, serverPort:int = 4322 ) -> bool:
    """Connects to a remote system running a squish server and performs a command to check if the 'AdaptivePlanningWorkflow.exe' is running

    :param str serverAddress: IP address of target Monaco system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :return: True or False
    :rtype bool:
    """
    remotesys = RemoteSystem(host=serverAddress, port=serverPort)
    options = {"timeout": 10}

    find_winaut_pid_command = ["cmd", "/c", "tasklist", "/FI", "IMAGENAME eq AdaptivePlanningWorkflow.exe", "/FO", "LIST", "|", "findstr", "PID:"]
    (exitcode, stdout, stderr) = remotesys.execute(find_winaut_pid_command, options=options)

    remotesys.close()
    if exitcode != "0":
        return False
    return True


def wait_for_adaptive_script_process_to_terminate(hostAddress:str, serverPort: int = 4322, waitInterval: int = 2, waitTimeout: int = 30) -> bool:
    """Waits for the AdaptivePlanningWorkflow.exe process to terminate on the remote system by polling the process list to check if the PID is
    still running. This function is used to wait for the Adaptive workflow script on Monaco to complete.

    :param str hostAddress: IP address of target Monaco system running a squish server
    :param int serverPort: Network port of running squish server on target system (Default is 4322)
    :param int waitInterval: Time in seconds to wait between each poll (Default is 2 seconds)
    :param int waitTimeout: Time in seconds to wait for the adaptive planning workflow process to terminate (Default is 30 seconds)

    :return bool: True if the process has terminated, False otherwise
    """
    try:
        return poll(lambda: is_monaco_adaptive_script_process_running(hostAddress, serverPort) == False,
                    step=waitInterval, timeout=waitTimeout)
    except TimeoutException as e:
        return False